// Generates supabase/seed.sql from supabase/content.js with deterministic UUIDs (re-runnable seed).
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const { themes, achievements } = require('../supabase/content');

const uuid = (key) => {
  const h = crypto.createHash('md5').update(key).digest('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;
};
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;

const out = [
  '-- GENERATED by scripts/generate-seed.js from supabase/content.js. Do not edit by hand.',
  '',
];

out.push(
  'insert into public.categories (id, name, description, emoji, sort_order, is_active) values',
);
out.push(
  themes
    .map(
      (t, i) =>
        `  (${q(uuid('cat:' + t.name))}, ${q(t.name)}, ${q(t.description)}, ${q(t.emoji)}, ${i + 1}, true)`,
    )
    .join(',\n'),
);
out.push(
  'on conflict (id) do update set name = excluded.name, description = excluded.description, emoji = excluded.emoji, sort_order = excluded.sort_order;',
  '',
);

// First 5 lessons are free; the rest unlock after the previous lesson is completed.
out.push(
  'insert into public.lessons (id, category_id, title, description, age_group, level, sort_order, is_locked) values',
);
out.push(
  themes
    .map(
      (t, i) =>
        `  (${q(uuid('lesson:' + t.name))}, ${q(uuid('cat:' + t.name))}, ${q(t.lesson)}, ${q(t.description)}, 'all', ${Math.floor(i / 5) + 1}, ${i + 1}, ${i >= 5})`,
    )
    .join(',\n'),
);
out.push(
  'on conflict (id) do update set title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, is_locked = excluded.is_locked;',
  '',
);

const vocabRows = [];
for (const t of themes) {
  for (const [word, translation, example, emoji, difficulty] of t.words) {
    vocabRows.push(
      `  (${q(uuid('vocab:' + t.name + ':' + word))}, ${q(uuid('lesson:' + t.name))}, ${q(word)}, ${q(translation)}, ${q(example)}, ${q(emoji)}, ${difficulty})`,
    );
  }
}
out.push(
  'insert into public.vocabulary (id, lesson_id, word, translation, example_sentence, emoji, difficulty) values',
);
out.push(vocabRows.join(',\n'));
out.push(
  'on conflict (id) do update set word = excluded.word, translation = excluded.translation, example_sentence = excluded.example_sentence, emoji = excluded.emoji, difficulty = excluded.difficulty;',
  '',
);

out.push(
  'insert into public.achievements (id, name, description, icon, requirement_type, requirement_value) values',
);
out.push(
  achievements
    .map(
      ([n, d, i, rt, rv]) =>
        `  (${q(uuid('ach:' + n))}, ${q(n)}, ${q(d)}, ${q(i)}, ${q(rt)}, ${rv})`,
    )
    .join(',\n'),
);
out.push(
  'on conflict (id) do update set name = excluded.name, description = excluded.description, icon = excluded.icon, requirement_type = excluded.requirement_type, requirement_value = excluded.requirement_value;',
  '',
);

const supabaseDir = path.join(__dirname, '..', 'supabase');
const seedSql = out.join('\n');

// setup.sql = every migration (in order) + seed, so one paste into the SQL Editor does everything.
const migrationsDir = path.join(supabaseDir, 'migrations');
const migrations = fs
  .readdirSync(migrationsDir)
  .filter((f) => f.endsWith('.sql'))
  .sort()
  .map(
    (f) =>
      `-- ===== migration: ${f} =====\n${fs.readFileSync(path.join(migrationsDir, f), 'utf8')}`,
  );
const setupSql = [
  '-- GENERATED by scripts/generate-seed.js (migrations + seed). Do not edit by hand.',
  '-- Paste the whole file into Supabase SQL Editor and click Run. Safe to run more than once.',
  '',
  ...migrations,
  '-- ===== seed data =====',
  seedSql,
].join('\n');
// seed.sql is the same file on purpose: running it alone on an empty database must not fail with
// 'relation does not exist'. Everything in it is idempotent.
fs.writeFileSync(path.join(supabaseDir, 'setup.sql'), setupSql);
fs.writeFileSync(path.join(supabaseDir, 'seed.sql'), setupSql);
console.log(
  `seed.sql written: ${themes.length} categories, ${vocabRows.length} words, ${achievements.length} achievements`,
);
